/// Asset path of the manifest.
pub const MANIFEST_PATH: &str = "quillshade/material/autogen/baked.ron";

/// Manifest format version this crate reads.
pub const MANIFEST_VERSION: u32 = 1;

/// Texture of a binding without a usable texture (missing in the manifest, failed to load).
pub const DEFAULT_TEXTURE: &str = "@internal/default";

/// Contents of `baked.ron`: every Texture asset and every material's values.
#[derive(Asset, TypePath, Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct BakedManifest {
    pub version: u32,
    /// Texture asset id (`textures/rock_albedo`, `@internal/default`, `@gradients/common/terrain`) → image.
    #[serde(default)]
    pub textures: BTreeMap<String, TextureDef>,
    /// Material asset id (`env/rock_wet`) → values.
    #[serde(default)]
    pub materials: BTreeMap<String, MaterialValues>,
    /// Reserved for material instances; always empty.
    #[serde(default)]
    pub instances: BTreeMap<String, ron::Value>,
}

impl BakedManifest {
    fn empty() -> Self {
        Self {
            version: MANIFEST_VERSION,
            textures: BTreeMap::new(),
            materials: BTreeMap::new(),
            instances: BTreeMap::new(),
        }
    }

    /// Parses the manifest text; a version other than [`MANIFEST_VERSION`] is an error.
    pub fn parse(text: &str) -> Result<Self, String> {
        let m: Self = ron::Options::default().from_str(text).map_err(|e| e.to_string())?;
        if m.version != MANIFEST_VERSION {
            return Err(format!("unsupported manifest version {} (expected {MANIFEST_VERSION})", m.version));
        }
        Ok(m)
    }
}

