/// Mirror of Bevy's `ImageAddressMode`.
#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum AddressModeDef {
    #[default]
    ClampToEdge,
    Repeat,
    MirrorRepeat,
    ClampToBorder,
}

/// Mirror of Bevy's `ImageFilterMode`.
#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum FilterModeDef {
    #[default]
    Nearest,
    Linear,
}

impl TextureSettingsDef {
    /// Writes these settings into Bevy's loader settings.
    fn apply(&self, s: &mut ImageLoaderSettings) {
        s.is_srgb = self.is_srgb;
        s.expand_grayscale = self.expand_grayscale;
        s.sampler = self.image_sampler();
    }

    /// The image sampler of these settings.
    fn image_sampler(&self) -> ImageSampler {
        match &self.sampler {
            None => ImageSampler::Default,
            Some(d) => ImageSampler::Descriptor(d.descriptor()),
        }
    }
}

impl SamplerDef {
    /// Bevy's sampler descriptor with these values (label, compare function and border color unset).
    pub fn descriptor(&self) -> ImageSamplerDescriptor {
        ImageSamplerDescriptor {
            address_mode_u: self.address_mode_u.into(),
            address_mode_v: self.address_mode_v.into(),
            address_mode_w: self.address_mode_w.into(),
            mag_filter: self.mag_filter.into(),
            min_filter: self.min_filter.into(),
            mipmap_filter: self.mipmap_filter.into(),
            lod_min_clamp: self.lod_min_clamp,
            lod_max_clamp: self.lod_max_clamp,
            anisotropy_clamp: self.anisotropy_clamp,
            ..default()
        }
    }
}

impl From<AddressModeDef> for ImageAddressMode {
    fn from(m: AddressModeDef) -> Self {
        match m {
            AddressModeDef::ClampToEdge => ImageAddressMode::ClampToEdge,
            AddressModeDef::Repeat => ImageAddressMode::Repeat,
            AddressModeDef::MirrorRepeat => ImageAddressMode::MirrorRepeat,
            AddressModeDef::ClampToBorder => ImageAddressMode::ClampToBorder,
        }
    }
}

impl From<FilterModeDef> for ImageFilterMode {
    fn from(m: FilterModeDef) -> Self {
        match m {
            FilterModeDef::Nearest => ImageFilterMode::Nearest,
            FilterModeDef::Linear => ImageFilterMode::Linear,
        }
    }
}

fn yes() -> bool {
    true
}

fn lod_max_clamp() -> f32 {
    32.0
}

fn anisotropy_clamp() -> u16 {
    1
}

/// Values of one material: uniform parameters by field (`inp_wetness`) and the Texture asset id of every texture
/// binding (`inp_albedo`, `ft_n02`), plus the material's layout feature (its material module's `LAYOUT_FEATURE`)
/// and the texture bindings in binding order.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Default)]
pub struct MaterialValues {
    #[serde(default)]
    pub params: BTreeMap<String, ParamValue>,
    #[serde(default)]
    pub textures: BTreeMap<String, String>,
    #[serde(default)]
    pub layout: String,
    #[serde(default)]
    pub bindings: Vec<String>,
}

/// A parameter value; colors are linear RGBA.
#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq)]
pub enum ParamValue {
    Float(f32),
    Vec2([f32; 2]),
    Vec3([f32; 3]),
    Vec4([f32; 4]),
    Color([f32; 4]),
    Bool(bool),
    Int(i32),
}

impl MaterialValues {
    /// Parameter `key` of `material` converted by `f`; `None` with a warning when it is missing or of another type
    /// (manifest and compiled code out of sync: the caller keeps the compiled default).
    fn param<T>(
        &self,
        material: &str,
        key: &str,
        expected: &str,
        f: impl FnOnce(&ParamValue) -> Option<T>,
    ) -> Option<T> {
        let Some(v) = self.params.get(key) else {
            warn!("baked material `{material}`: no value for `{key}` in the manifest; keeping the compiled default");
            return None;
        };
        let r = f(v);
        if r.is_none() {
            warn!(
                "baked material `{material}`: `{key}` is {v:?}, expected {expected}; keeping the compiled default \
                 (rebuild the game)"
            );
        }
        r
    }

    pub fn float(&self, material: &str, key: &str) -> Option<f32> {
        self.param(material, key, "Float", |v| match v {
            ParamValue::Float(x) => Some(*x),
            _ => None,
        })
    }

    pub fn vec2(&self, material: &str, key: &str) -> Option<Vec2> {
        self.param(material, key, "Vec2", |v| match v {
            ParamValue::Vec2(x) => Some(Vec2::from_array(*x)),
            _ => None,
        })
    }

    pub fn vec3(&self, material: &str, key: &str) -> Option<Vec3> {
        self.param(material, key, "Vec3", |v| match v {
            ParamValue::Vec3(x) => Some(Vec3::from_array(*x)),
            _ => None,
        })
    }

    pub fn vec4(&self, material: &str, key: &str) -> Option<Vec4> {
        self.param(material, key, "Vec4", |v| match v {
            ParamValue::Vec4(x) => Some(Vec4::from_array(*x)),
            _ => None,
        })
    }

    /// A color as its uniform value (linear RGBA).
    pub fn color(&self, material: &str, key: &str) -> Option<Vec4> {
        self.param(material, key, "Color", |v| match v {
            ParamValue::Color(x) => Some(Vec4::from_array(*x)),
            _ => None,
        })
    }

    pub fn boolean(&self, material: &str, key: &str) -> Option<bool> {
        self.param(material, key, "Bool", |v| match v {
            ParamValue::Bool(x) => Some(*x),
            _ => None,
        })
    }

    /// Texture asset id of binding `key`; [`DEFAULT_TEXTURE`] with a warning when it is missing.
    pub fn texture(&self, material: &str, key: &str) -> &str {
        match self.textures.get(key) {
            Some(id) => id,
            None => {
                warn!("baked material `{material}`: no texture for `{key}` in the manifest; using {DEFAULT_TEXTURE}");
                DEFAULT_TEXTURE
            }
        }
    }
}

/// Loads `*.baked.ron` as a [`BakedManifest`].
#[derive(Default, TypePath)]
pub struct ManifestLoader;

impl AssetLoader for ManifestLoader {
    type Asset = BakedManifest;
    type Settings = ();
    type Error = BevyError;

    async fn load(
        &self,
        reader: &mut dyn Reader,
        _settings: &(),
        _load_context: &mut LoadContext<'_>,
    ) -> Result<BakedManifest, BevyError> {
        let mut bytes = Vec::new();
        reader.read_to_end(&mut bytes).await?;
        Ok(BakedManifest::parse(std::str::from_utf8(&bytes)?)?)
    }

    fn extensions(&self) -> &[&str] {
        &["baked.ron"]
    }
}

/// Texture load progress, written whenever a count changes (and once when loading starts). `total` is the number of
/// textures in the compiled manifest (every Texture asset, the internal ones and the baked gradient collections; a
/// manifest hot reload before [`BakedMaterialsReady`] may add the textures it newly references); loading is over when
/// `loaded + failed == total`. Textures a later hot reload loads are not reported.
#[derive(Message, Clone, Copy, Debug, PartialEq, Eq)]
pub struct BakedMaterialsProgress {
    pub loaded: u32,
    pub failed: u32,
    pub total: u32,
}

/// Written once, when every texture has loaded or failed. Materials exist (and render) before that: Bevy waits for
/// their images on its own; a texture that failed is replaced by `@internal/default` in every material using it.
#[derive(Message, Clone, Copy, Debug)]
pub struct BakedMaterialsReady;

/// Starts loading the baked materials and reports progress (design §3.1):
///
/// ```no_run
/// fn start(mut loader: quillshade::material::BakedMaterialsLoader) {
///     let textures = loader.load(); // idempotent
///     bevy::log::info!("loading {textures} textures");
/// }
/// ```
///
/// Optional: without a `load()` call [`BakedPlugin`] starts loading in the first `PreUpdate` (decision 0027). Call it
/// to use [`BakedTextures`] in `Startup` or to size a loading screen. [`BakedMaterials`] holds reserved handles from
/// the start. `load()` fills [`BakedTextures`] at once (so a system running after it, even in the same schedule, can
/// use `tex.textures.sprite`), the materials are inserted behind their handles on the next `PreUpdate`, then
/// [`BakedMaterialsProgress`] / [`BakedMaterialsReady`] follow.
#[derive(SystemParam)]
pub struct BakedMaterialsLoader<'w> {
    state: ResMut<'w, BakedState>,
    server: Res<'w, AssetServer>,
    textures: ResMut<'w, BakedTextures>,
}

impl BakedMaterialsLoader<'_> {
    /// Starts loading every texture of the compiled manifest with its Texture asset settings and fills
    /// [`BakedTextures`]; the materials follow on the next `PreUpdate`, then `baked.ron` itself is loaded as an asset
    /// (design §3.3 step 2). Idempotent. Returns the number of textures being loaded ([`BakedMaterialsProgress`]
    /// `total`; a call after loading started returns the current one).
    pub fn load(&mut self) -> u32 {
        if !self.state.started {
            self.start(crate::material::COMPILED_MANIFEST, true);
        }
        self.state.progress().total
    }

    /// Loads from `manifest` instead of [`crate::material::COMPILED_MANIFEST`] (tests); ignored once loading has
    /// started. `manifest` stands for the compiled snapshot *and* the runtime manifest: `baked.ron` is not loaded, so
    /// nothing overlays it.
    #[doc(hidden)]
    pub fn load_from_str(&mut self, manifest: &str) {
        if self.state.started {
            warn!("baked materials: load_from_str after loading started; ignored");
            return;
        }
        self.start(manifest, false);
    }

    /// Starts loading from manifest `text`; `hot_reload`: then load `baked.ron` as an asset and apply it on top.
    fn start(&mut self, text: &str, hot_reload: bool) {
        let manifest = BakedManifest::parse(text).unwrap_or_else(|e| {
            error!("baked materials: the compiled manifest does not parse ({e}); using compiled defaults");
            BakedManifest::empty()
        });
        let mut textures = BTreeMap::new();
        for (id, def) in &manifest.textures {
            let entry = TextureEntry::load(&self.server, def);
            self.textures.set(id, entry.handle.clone());
            textures.insert(id.clone(), entry);
        }
        // A field without a manifest entry: its Texture asset had an error at regeneration (E011 / E012 / E013).
        let fallback = textures.get(DEFAULT_TEXTURE).map(|e| e.handle.clone()).unwrap_or_default();
        for id in BakedTextures::IDS.iter().filter(|id| !manifest.textures.contains_key(**id)) {
            warn!("baked materials: texture `{id}` is not in the manifest (invalid Texture asset); using the default");
            self.textures.set(id, fallback.clone());
        }

        for id in manifest.materials.keys() {
            if !BakedMaterials::IDS.contains(&id.as_str()) {
                warn!("baked materials: material `{id}` is not compiled into the game; ignored (rebuild the game)");
            }
        }
        let mut materials = BTreeMap::new();
        for id in BakedMaterials::IDS {
            let values = manifest.materials.get(*id).cloned().unwrap_or_else(|| {
                warn!("baked materials: material `{id}` is not in the manifest; using compiled defaults");
                MaterialValues::default()
            });
            materials.insert(id.to_string(), values);
        }
        let state = &mut *self.state;
        state.started = true;
        state.pending_build = true;
        state.textures = textures;
        state.base_materials = materials.clone();
        state.materials = materials;
        state.base_textures = manifest.textures;
        if hot_reload {
            state.manifest = Some(self.server.load(MANIFEST_PATH));
        }
    }

    /// Current counts; before `load()`, `total` is the number of textures of the compiled manifest and nothing is
    /// loaded.
    pub fn progress(&self) -> BakedMaterialsProgress {
        self.state.progress()
    }

    /// `true` once every texture has loaded or failed ([`BakedMaterialsReady`] was written).
    pub fn is_ready(&self) -> bool {
        self.state.ready
    }
}

/// Load state of one texture.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TextureStatus {
    Loading,
    Loaded,
    Failed,
}

/// One texture of the manifest being loaded.
struct TextureEntry {
    path: String,
    handle: Handle<Image>,
    status: TextureStatus,
    /// Settings the image was loaded with (the sampler: the one it should have).
    settings: TextureSettingsDef,
    /// `settings.sampler` is not set on the image yet (it is still loading).
    sampler_pending: bool,
}

impl TextureEntry {
    /// Starts loading `def` with its settings.
    fn load(server: &AssetServer, def: &TextureDef) -> Self {
        let settings = def.settings.clone();
        let handle: Handle<Image> = server
            .load_builder()
            .with_settings(move |s: &mut ImageLoaderSettings| settings.apply(s))
            .load(def.path.clone());
        Self {
            path: def.path.clone(),
            handle,
            status: TextureStatus::Loading,
            settings: def.settings.clone(),
            sampler_pending: false,
        }
    }
}

/// Bookkeeping of the loader (design §3.1 `BakedShaderAssets`): flags, the image handle and status of every manifest
/// texture, the values every material was built from, the compiled snapshot the runtime manifest overlays, the
/// manifest asset.
#[doc(hidden)]
#[derive(Resource, Default)]
pub struct BakedState {
    started: bool,
    /// `load()` ran, the materials are not inserted yet.
    pending_build: bool,
    ready: bool,
    /// Texture asset id → image.
    textures: BTreeMap<String, TextureEntry>,
    /// Material id → values it was built from.
    materials: BTreeMap<String, MaterialValues>,
    /// Textures of the compiled snapshot (the manifest `load()` started from).
    base_textures: BTreeMap<String, TextureDef>,
    /// Values of every compiled material in the compiled snapshot.
    base_materials: BTreeMap<String, MaterialValues>,
    /// `baked.ron` as an asset (hot reload); `None` after `load_from_str`.
    manifest: Option<Handle<BakedManifest>>,
    /// Last written progress.
    sent: Option<BakedMaterialsProgress>,
    /// Keys of the hot reload warnings already logged (each is logged once).
    warned: BTreeSet<String>,
}

impl BakedState {
    /// A texture is still loading (the initial load or one started by a hot reload).
    fn loading(&self) -> bool {
        self.textures.values().any(|t| t.status == TextureStatus::Loading)
    }

    /// A sampler change waits for its image.
    fn sampler_pending(&self) -> bool {
        self.textures.values().any(|t| t.sampler_pending)
    }

    /// Materials bound to one of `textures`; all of them when the default texture is among them (it changes the
    /// image of every binding that fell back to it).
    fn users(&self, textures: &BTreeSet<String>) -> Vec<String> {
        let all = textures.contains(DEFAULT_TEXTURE);
        self.materials
            .iter()
            .filter(|(_, v)| all || v.textures.values().any(|t| textures.contains(t)))
            .map(|(id, _)| id.clone())
            .collect()
    }

    fn progress(&self) -> BakedMaterialsProgress {
        if !self.started {
            let total = BakedManifest::parse(crate::material::COMPILED_MANIFEST).map_or(0, |m| m.textures.len() as u32);
            return BakedMaterialsProgress { loaded: 0, failed: 0, total };
        }
        let count = |s: TextureStatus| self.textures.values().filter(|t| t.status == s).count() as u32;
        BakedMaterialsProgress {
            loaded: count(TextureStatus::Loaded),
            failed: count(TextureStatus::Failed),
            total: self.textures.len() as u32,
        }
    }

    /// Image of every usable texture: a failed one is replaced by [`DEFAULT_TEXTURE`], a failed default by Bevy's
    /// white image; plus the fallback for ids that are not in the manifest.
    fn images(&self) -> (BTreeMap<String, Handle<Image>>, Handle<Image>) {
        let fallback = match self.textures.get(DEFAULT_TEXTURE) {
            Some(t) if t.status != TextureStatus::Failed => t.handle.clone(),
            _ => Handle::default(),
        };
        let images = self
            .textures
            .iter()
            .map(|(id, t)| {
                let h = if t.status == TextureStatus::Failed { fallback.clone() } else { t.handle.clone() };
                (id.clone(), h)
            })
            .collect();
        (images, fallback)
    }
}

/// Registers the baked materials runtime without render plugins: every material asset type (unless a material
/// plugin did it already), the manifest asset and loader, the messages, [`BakedTextures`], the loader systems;
/// [`BakedMaterials`] is reserved in `finish`. [`crate::material::QuillshadeMaterialInternalPlugin`] (added by
/// [`crate::QuillshadePlugin`]) adds it after the material plugins; alone it serves headless tests.
#[doc(hidden)]
pub struct BakedPlugin;

impl Plugin for BakedPlugin {
    fn build(&self, app: &mut App) {
        BakedMaterials::init_assets(app);
        init_asset::<BakedManifest>(app);
        app.register_asset_loader(ManifestLoader)
            .add_message::<BakedMaterialsProgress>()
            .add_message::<BakedMaterialsReady>()
            .init_resource::<BakedState>()
            .init_resource::<BakedTextures>()
            .add_systems(
                PreUpdate,
                (
                    auto_load.run_if(|s: Res<BakedState>| !s.started),
                    insert_materials.run_if(|s: Res<BakedState>| s.pending_build),
                    apply_manifest.run_if(|s: Res<BakedState>| s.manifest.is_some()),
                    track_progress.run_if(|s: Res<BakedState>| s.started && (!s.ready || s.loading())),
                    apply_samplers.run_if(|s: Res<BakedState>| s.sampler_pending()),
                )
                    .chain(),
            );
    }

    fn finish(&self, app: &mut App) {
        // After every `build`: all `Assets<M>` exist.
        let baked = BakedMaterials::reserve(app.world_mut());
        app.insert_resource(baked);
    }
}

/// `init_asset::<A>()` unless `Assets<A>` exists (a second `init_asset` would replace the storage and duplicate the
/// asset systems).
pub(crate) fn init_asset<A: Asset>(app: &mut App) {
    if !app.world().contains_resource::<Assets<A>>() {
        app.init_asset::<A>();
    }
}

/// Inserts material `m` at its reserved handle.
#[allow(dead_code)] // unused in a project without materials
pub(crate) fn insert_material<M: Asset>(world: &mut World, handle: &Handle<M>, m: M) {
    if let Err(e) = world.resource_mut::<Assets<M>>().insert(handle.id(), m) {
        error!("baked materials: cannot insert a material: {e}");
    }
}

/// Whether the asset behind `handle` exists.
#[allow(dead_code)] // unused in a project without materials
pub(crate) fn has_material<M: Asset>(world: &World, handle: &Handle<M>) -> bool {
    world.resource::<Assets<M>>().contains(handle.id())
}

/// Starts loading when the game did not call [`BakedMaterialsLoader::load`] before the first `PreUpdate`.
fn auto_load(mut loader: BakedMaterialsLoader) {
    loader.load();
}

/// Inserts every material at its reserved handle after `load()` (design §3.3 step 2; an exclusive system because it
/// writes every `Assets<M>`).
fn insert_materials(world: &mut World) {
    let mut state = world.resource_mut::<BakedState>();
    state.pending_build = false;
    let ids: Vec<String> = state.materials.keys().cloned().collect();
    build_materials(world, &ids);
}

/// (Re)builds materials `ids` from their values and the current images, at their reserved handles.
fn build_materials(world: &mut World, ids: &[String]) {
    let baked = world.resource::<BakedMaterials>().clone();
    let state = world.resource::<BakedState>();
    let (images, fallback) = state.images();
    let todo: Vec<(&String, MaterialValues)> =
        ids.iter().filter_map(|id| state.materials.get(id).map(|v| (id, v.clone()))).collect();
    let tex = |id: &str| -> Handle<Image> {
        images.get(id).cloned().unwrap_or_else(|| {
            warn!("baked materials: texture `{id}` is not in the manifest; using {DEFAULT_TEXTURE}");
            fallback.clone()
        })
    };
    for (id, values) in todo {
        baked.insert(world, id, &values, &tex);
    }
}

/// Follows the texture loads: counts loaded / failed, switches the materials of a failed texture to
/// [`DEFAULT_TEXTURE`], writes [`BakedMaterialsProgress`] on change and [`BakedMaterialsReady`] once (design §3.3
/// step 3). After Ready it only follows the textures a hot reload loads (failures), without messages.
fn track_progress(world: &mut World) {
    let server = world.resource::<AssetServer>().clone();
    let mut state = world.resource_mut::<BakedState>();
    let mut failed = BTreeSet::new();
    for (id, t) in state.textures.iter_mut().filter(|(_, t)| t.status == TextureStatus::Loading) {
        match server.load_state(&t.handle) {
            LoadState::Loaded => t.status = TextureStatus::Loaded,
            LoadState::Failed(e) => {
                error!(
                    "baked materials: texture `{id}` (`{}`) failed to load: {e}; materials using it get {DEFAULT_TEXTURE}",
                    t.path
                );
                t.status = TextureStatus::Failed;
                failed.insert(id.clone());
            }
            LoadState::NotLoaded | LoadState::Loading => {}
        }
    }
    if !failed.is_empty() {
        let ids = state.users(&failed);
        build_materials(world, &ids);
    }
    let mut state = world.resource_mut::<BakedState>();
    if state.ready {
        return;
    }
    let progress = state.progress();
    if state.sent != Some(progress) {
        state.sent = Some(progress);
        world.write_message(progress);
    }
    if progress.loaded + progress.failed == progress.total {
        world.resource_mut::<BakedState>().ready = true;
        world.write_message(BakedMaterialsReady);
    }
}

/// Logs each hot reload warning once per key (a manifest is applied on every change; an out-of-sync key would
/// otherwise warn on every save in the editor).
fn warn_once(warned: &mut BTreeSet<String>, key: String, message: impl FnOnce() -> String) {
    if warned.insert(key) {
        warn!("baked materials: {}", message());
    }
}

/// Manifest asset events and load failures.
type ManifestMessages = (
    MessageReader<'static, 'static, AssetEvent<BakedManifest>>,
    MessageReader<'static, 'static, AssetLoadFailedEvent<BakedManifest>>,
);

/// Applies `baked.ron` whenever it loads or changes (design §3.3 step 4; changes on disk need the game's
/// `file_watcher` feature). A manifest that fails to load (garbage, another version) is reported and changes nothing.
fn apply_manifest(world: &mut World, messages: &mut SystemState<ManifestMessages>) {
    let Some(tracked) = world.resource::<BakedState>().manifest.as_ref().map(|h| h.id()) else {
        return;
    };
    let Ok((mut events, mut failures)) = messages.get_mut(world) else {
        return;
    };
    // Every event is read (not `any`, which stops at the first match and leaves the rest for a redundant second
    // `apply` next frame).
    let changed = events
        .read()
        .filter(|e| match e {
            AssetEvent::Added { id } | AssetEvent::Modified { id } | AssetEvent::LoadedWithDependencies { id } => {
                *id == tracked
            }
            AssetEvent::Removed { .. } | AssetEvent::Unused { .. } => false,
        })
        .count()
        > 0;
    for f in failures.read().filter(|f| f.id == tracked) {
        warn!("baked materials: `{}` failed to load ({}); keeping the current materials and textures", f.path, f.error);
    }
    if !changed {
        return;
    }
    let Some(manifest) = world.resource::<Assets<BakedManifest>>().get(tracked).cloned() else {
        return;
    };
    apply(world, &manifest);
}

/// The compiled snapshot overlaid by `runtime` (design §3.2, §3.3 step 4): every compiled material with every
/// compiled key, and every compiled texture plus the uncompiled ones a material refers to. A key the runtime
/// manifest lacks or retypes keeps the compiled value; a key unknown to the compiled code is ignored (both with a
/// warning: the game needs a rebuild). Texture bindings of a material whose layout is unchanged are matched by
/// position, so another fixed texture node wired in (another `ft_*` name, same binding) takes effect.
fn overlay(
    base_textures: &BTreeMap<String, TextureDef>,
    base_materials: &BTreeMap<String, MaterialValues>,
    runtime: &BakedManifest,
    warned: &mut BTreeSet<String>,
) -> (BTreeMap<String, TextureDef>, BTreeMap<String, MaterialValues>) {
    for id in runtime.materials.keys().filter(|id| !base_materials.contains_key(*id)) {
        warn_once(warned, format!("material {id}"), || {
            format!("material `{id}` of the manifest is not compiled into the game; ignored (rebuild the game)")
        });
    }
    let known = |t: &str| base_textures.contains_key(t) || runtime.textures.contains_key(t);
    let mut materials = BTreeMap::new();
    for (id, base) in base_materials {
        let Some(new) = runtime.materials.get(id) else {
            warn_once(warned, format!("material {id} missing"), || {
                format!("material `{id}` is not in the manifest; keeping its compiled values")
            });
            materials.insert(id.clone(), base.clone());
            continue;
        };
        let mut v = base.clone();
        for (key, value) in v.params.iter_mut() {
            match new.params.get(key) {
                None => warn_once(warned, format!("param {id} {key} missing"), || {
                    format!(
                        "`{key}` of material `{id}` is not in the manifest; keeping the compiled value (rebuild the game)"
                    )
                }),
                Some(n) if std::mem::discriminant(n) == std::mem::discriminant(value) => *value = *n,
                Some(n) => warn_once(warned, format!("param {id} {key} type"), || {
                    format!(
                        "`{key}` of material `{id}` is {n:?} in the manifest but {value:?} in the game; keeping the \
                         compiled value (rebuild the game)"
                    )
                }),
            }
        }
        for key in new.params.keys().filter(|k| !base.params.contains_key(*k)) {
            warn_once(warned, format!("param {id} {key}"), || {
                format!(
                    "parameter `{key}` of material `{id}` is not compiled into the game; ignored (rebuild the game)"
                )
            });
        }
        let same_layout = !base.layout.is_empty() && base.layout == new.layout;
        if !base.layout.is_empty() && !new.layout.is_empty() && !same_layout {
            warn_once(warned, format!("layout {id} {}", new.layout), || {
                format!(
                    "material `{id}` changed its parameters, texture bindings, World Position Offset, blend mode, \
                     two-sided or shading; its shader does not compile until the game is rebuilt"
                )
            });
        }
        // Same layout: the runtime binding at the position of a compiled one (same number, maybe another name).
        let renamed: BTreeMap<&String, &String> = match same_layout && base.bindings.len() == new.bindings.len() {
            true => base.bindings.iter().zip(&new.bindings).collect(),
            false => BTreeMap::new(),
        };
        for (key, texture) in v.textures.iter_mut() {
            let key = renamed.get(key).copied().unwrap_or(key);
            match new.textures.get(key) {
                None => warn_once(warned, format!("binding {id} {key} missing"), || {
                    format!("texture `{key}` of material `{id}` is not in the manifest; keeping the compiled texture")
                }),
                Some(t) if known(t) => texture.clone_from(t),
                Some(t) => {
                    warn_once(warned, format!("binding {id} {key} {t}"), || {
                        format!(
                            "texture `{key}` of material `{id}` is `{t}`, which no manifest has; using {DEFAULT_TEXTURE}"
                        )
                    });
                    *texture = DEFAULT_TEXTURE.to_string();
                }
            }
        }
        let mapped: BTreeSet<&String> = renamed.values().copied().collect();
        for key in new.textures.keys().filter(|k| !base.textures.contains_key(*k) && !mapped.contains(k)) {
            warn_once(warned, format!("binding {id} {key}"), || {
                format!("texture `{key}` of material `{id}` is not compiled into the game; ignored (rebuild the game)")
            });
        }
        materials.insert(id.clone(), v);
    }

    let mut textures = BTreeMap::new();
    for (id, base) in base_textures {
        let def = runtime.textures.get(id).unwrap_or_else(|| {
            warn_once(warned, format!("texture {id} missing"), || {
                format!("texture `{id}` is not in the manifest; keeping the compiled one")
            });
            base
        });
        textures.insert(id.clone(), def.clone());
    }
    let used: BTreeSet<&String> = materials.values().flat_map(|v| v.textures.values()).collect();
    for (id, def) in runtime.textures.iter().filter(|(id, _)| !base_textures.contains_key(*id)) {
        if BakedTextures::IDS.contains(&id.as_str()) {
            // A field whose Texture asset had an error at build time and is valid now.
            textures.insert(id.clone(), def.clone());
        } else if used.contains(id) {
            warn_once(warned, format!("texture {id} used"), || {
                format!(
                    "texture `{id}` is not compiled into the game; loaded by path for the materials using it, not in \
                     BakedTextures (rebuild the game)"
                )
            });
            textures.insert(id.clone(), def.clone());
        } else {
            warn_once(warned, format!("texture {id}"), || {
                format!("texture `{id}` is not compiled into the game; ignored (rebuild the game)")
            });
        }
    }
    (textures, materials)
}

/// Diffs `runtime` (overlaid on the compiled snapshot) against the current state and applies it: a re-pointed or
/// new texture is loaded, a sampler change is set on the image (once it is loaded), the materials whose values or
/// images changed are rebuilt at their handles. Loader-only settings (`is_srgb`, `expand_grayscale`) cannot change
/// without a rebuild of the game (Bevy keeps the first load's settings).
fn apply(world: &mut World, runtime: &BakedManifest) {
    if runtime.version != MANIFEST_VERSION {
        warn!(
            "baked materials: manifest version {} is not {MANIFEST_VERSION}; ignored (rebuild the game)",
            runtime.version
        );
        return;
    }
    let server = world.resource::<AssetServer>().clone();
    let ids = world.resource_scope(|world, mut state: Mut<BakedState>| {
        let state = &mut *state;
        let (textures, materials) = overlay(&state.base_textures, &state.base_materials, runtime, &mut state.warned);
        let mut baked_textures = world.resource_mut::<BakedTextures>();
        let mut changed = BTreeSet::new();
        for (id, def) in &textures {
            match state.textures.get_mut(id) {
                Some(e) if e.path == def.path => {
                    let (old, new) = (&e.settings, &def.settings);
                    if old.is_srgb != new.is_srgb || old.expand_grayscale != new.expand_grayscale {
                        warn_once(&mut state.warned, format!("texture {id} settings"), || {
                            format!(
                                "texture `{id}`: is_srgb / expand_grayscale changed; Bevy cannot reload an image with \
                                 new loader settings (rebuild the game)"
                            )
                        });
                    }
                    if e.settings.sampler != def.settings.sampler {
                        e.settings.sampler = def.settings.sampler;
                        e.sampler_pending = true;
                    }
                }
                _ => {
                    // Re-pointed to another file, or new: entities that took the old image keep it. The file may be
                    // loaded already (Bevy then returns that image and ignores our settings): set the sampler once it
                    // is there (a no-op when it already matches).
                    let mut entry = TextureEntry::load(&server, def);
                    entry.sampler_pending = true;
                    baked_textures.set(id, entry.handle.clone());
                    state.textures.insert(id.clone(), entry);
                    changed.insert(id.clone());
                }
            }
        }
        let dropped: Vec<String> = state.textures.keys().filter(|id| !textures.contains_key(*id)).cloned().collect();
        for id in dropped {
            state.textures.remove(&id);
            // A `BakedTextures` field of a dropped texture falls back to the default texture.
            let fallback = state.textures.get(DEFAULT_TEXTURE).map(|e| e.handle.clone()).unwrap_or_default();
            baked_textures.unset(&id, fallback);
            changed.insert(id);
        }
        let mut ids: BTreeSet<String> = state.users(&changed).into_iter().collect();
        for (id, v) in materials {
            if state.materials.get(&id) != Some(&v) {
                ids.insert(id.clone());
                state.materials.insert(id, v);
            }
        }
        ids.into_iter().collect::<Vec<_>>()
    });
    build_materials(world, &ids);
}

/// Sets a changed sampler on its image once the image is loaded, then touches (re-inserts) every material using it:
/// Bevy rebuilds the GPU sampler, but a material keeps its bind group until the material itself changes.
fn apply_samplers(world: &mut World) {
    let touched = world.resource_scope(|world, mut state: Mut<BakedState>| {
        let mut images = world.resource_mut::<Assets<Image>>();
        let mut touched = BTreeSet::new();
        for (id, e) in state.textures.iter_mut().filter(|(_, e)| e.sampler_pending) {
            let want = e.settings.image_sampler();
            match images.get(&e.handle) {
                Some(image) if image.sampler == want => e.sampler_pending = false,
                Some(_) => {
                    if let Some(mut image) = images.get_mut(&e.handle) {
                        image.sampler = want;
                    }
                    e.sampler_pending = false;
                    touched.insert(id.clone());
                }
                None => match e.status {
                    TextureStatus::Loading => {}
                    // Materials use the default texture.
                    TextureStatus::Failed => e.sampler_pending = false,
                    TextureStatus::Loaded => {
                        warn!(
                            "baked materials: texture `{id}` keeps no main-world data (asset usage); its sampler \
                             cannot change (rebuild the game)"
                        );
                        e.sampler_pending = false;
                    }
                },
            }
        }
        touched
    });
    if !touched.is_empty() {
        let ids = world.resource::<BakedState>().users(&touched);
        build_materials(world, &ids);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The embedded manifest parses, has an entry for every field of [`BakedMaterials`], and every texture of it is a
    /// field of [`BakedTextures`] (a field may lack an entry: its Texture asset had an error, it gets the default).
    #[test]
    fn compiled_manifest_parses() {
        let m = BakedManifest::parse(crate::material::COMPILED_MANIFEST).expect("COMPILED_MANIFEST parses");
        for id in BakedMaterials::IDS {
            assert!(m.materials.contains_key(*id), "material `{id}` is not in the manifest");
        }
        let tex = BakedTextures::default();
        for id in BakedTextures::IDS {
            assert!(tex.field(id).is_some(), "BakedTextures::field(`{id}`)");
        }
        for id in m.textures.keys() {
            assert!(tex.field(id).is_some(), "manifest texture `{id}` has no BakedTextures field");
        }
        assert!(m.textures.contains_key(DEFAULT_TEXTURE));
    }
}
